@push('script')<script>(()=>{const search=document.getElementById('checklist-search'),rows=[...document.querySelectorAll('.checklist-entry')],labels={PENDING:['A conferir','secondary'],OK:['Conforme','success'],NA:['Não se aplica','dark'],ISSUE:['Apontamento','danger']};let filter='ALL';const refresh=()=>{const term=search.value.toLowerCase();rows.forEach(row=>{const hide=(filter!=='ALL'&&row.dataset.status!==filter)||!row.dataset.search.includes(term);row.classList.toggle('d-none',hide);const obs=document.getElementById('obs-'+row.querySelector('.qc-choice')?.dataset.entry);if(obs&&hide)obs.classList.add('d-none')})};const set=(id,status)=>{const select=document.getElementById('status-'+id),row=select.closest('tr'),obs=document.getElementById('obs-'+id),[text,tone]=labels[status];select.value=status;row.dataset.status=status;row.querySelectorAll('.qc-choice').forEach(b=>b.classList.toggle('active',b.dataset.value===status));row.querySelector('.status-label').className='badge text-bg-'+tone+' status-label';row.querySelector('.status-label').textContent=text;obs.classList.toggle('d-none',status!=='ISSUE');const checked=rows.filter(r=>r.dataset.status!=='PENDING').length;document.getElementById('qc-checked').textContent=checked;document.getElementById('qc-progress').style.width=Math.round(checked/rows.length*100)+'%'};search?.addEventListener('input',refresh);document.querySelectorAll('.checklist-filter').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('.checklist-filter').forEach(x=>x.classList.toggle('active',x===b));refresh()}));document.querySelectorAll('.qc-choice').forEach(b=>b.addEventListener('click',()=>set(b.dataset.entry,b.dataset.value)));document.querySelectorAll('.qc-bulk').forEach(b=>b.addEventListener('click',()=>document.querySelectorAll('#'+b.dataset.section+' .checklist-entry').forEach(row=>{const id=row.querySelector('.qc-choice').dataset.entry;set(id,b.dataset.value)})))})();</script>@endpush
